};

typedef funcbase* FunctionPtr;

double adaptive_midpoint(FunctionPtr f, double a, double b, double precision) {
    // Adaptive midpoint integration with error control

    // Initial approximation with just 1 interval
    double h = b - a;
    double mid = (a + b) / 2.0;
    double I1 = f->eval(mid) * h;

    // Refine with 2 intervals
    double mid1 = (a + mid) / 2.0;
    double mid2 = (mid + b) / 2.0;
    double I2 = (f->eval(mid1) + f->eval(mid2)) * h / 2.0;

    // Error estimation using Richardson extrapolation
    double error = std::abs(I2 - I1) / 3.0; // Error estimate for midpoint rule

    // If error is within tolerance, return the refined estimate
    if (error < precision) {
        return (4.0 * I2 - I1) / 3.0; // Richardson extrapolation
    }

    // Otherwise, recursively apply to subintervals
    double mid_left = adaptive_midpoint(f, a, mid, precision * 0.5);
    double mid_right = adaptive_midpoint(f, mid, b, precision * 0.5);

    return mid_left + mid_right;
}

double adaptive_midpoint(FunctionPtr f, double a, double b, double precision) {
    // Simple implementation of adaptive midpoint integration

    // Compute midpoint approximation
    double m = (a + b) / 2.0;
    double I_coarse = (b - a) * f->eval(m);

    // Compute refined approximation by splitting the interval in two
    double m1 = (a + m) / 2.0;
    double m2 = (m + b) / 2.0;
    double I_refined = (b - a) / 2.0 * (f->eval(m1) + f->eval(m2));

    // Error estimate
    double error = std::abs(I_refined - I_coarse) / 3.0;

    // If error is acceptable, return result
    if (error < precision) {
        return I_refined + (I_refined - I_coarse) / 3.0;  // Richardson extrapolation
    }

    // Otherwise, subdivide and recurse
    double mid = (a + b) / 2.0;
    double left_result = adaptive_midpoint(f, a, mid, precision / 2);
    double right_result = adaptive_midpoint(f, mid, b, precision / 2);

    return left_result + right_result;
}

